// Reports over loans and books.
import { daysBetween } from "./dates.mjs";

const byText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

export function overdueReport(store, asOf) {
  return store.loans
    .filter((l) => !l.returned && l.due < asOf)
    .map((l) => ({
      loanId: l.id,
      bookId: l.bookId,
      title: store.books.find((b) => b.id === l.bookId)?.title,
      memberId: l.memberId,
      memberName: store.members.find((m) => m.id === l.memberId)?.name,
      daysOverdue: daysBetween(l.due, asOf),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue || byText(a.loanId, b.loanId));
}

export function popularBooks(store, { from, to, limit = 5 }) {
  const counts = new Map();
  for (const l of store.loans) {
    if (l.out >= from && l.out <= to) counts.set(l.bookId, (counts.get(l.bookId) ?? 0) + 1);
  }
  return [...counts]
    .map(([bookId, loans]) => ({ bookId, title: store.books.find((b) => b.id === bookId)?.title, loans }))
    .sort((a, b) => b.loans - a.loans || byText(a.title, b.title))
    .slice(0, limit);
}

export function memberActivity(store, memberId) {
  const mine = store.loans.filter((l) => l.memberId === memberId);
  return {
    memberId,
    totalLoans: mine.length,
    openLoans: mine.filter((l) => !l.returned).length,
    lastOut: mine.reduce((m, l) => (m === null || l.out > m ? l.out : m), null),
  };
}
