// CSV export/import for books.
import { addBook } from "./store.mjs";

const HEADER = ["id", "title", "author", "year", "tags", "copies"];

const quote = (v) => {
  const s = String(v ?? "");
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = [HEADER.join(",")];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, (b.tags ?? []).join(";"), b.copies].map(quote).join(","));
  }
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }] where line is the 1-based line a record starts on.
function parse(text) {
  const records = [];
  let fields = [];
  let field = "";
  let inQuotes = false;
  let line = 1;
  let start = 1;
  let any = false;
  const endRecord = () => {
    fields.push(field);
    if (any || fields.length > 1) records.push({ line: start, fields });
    fields = [];
    field = "";
    any = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQuotes = false;
      } else {
        if (c === "\n") line++;
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
      any = true;
    } else if (c === ",") {
      fields.push(field);
      field = "";
      any = true;
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      endRecord();
      line++;
      start = line;
    } else {
      field += c;
      any = true;
    }
  }
  if (any || field || fields.length) endRecord();
  return records;
}

const WHOLE = /^-?\d+$/;

export function importBooks(store, text) {
  const records = parse(text);
  const result = { added: 0, errors: [] };
  if (!records.length) return result;
  const cols = records[0].fields.map((h) => h.trim());
  for (const { line, fields } of records.slice(1)) {
    const get = (name) => {
      const i = cols.indexOf(name);
      return i < 0 ? "" : (fields[i] ?? "").trim();
    };
    const title = get("title");
    const author = get("author");
    const year = get("year");
    const copies = get("copies");
    let message = null;
    if (!title) message = "title is required";
    else if (!author) message = "author is required";
    else if (!WHOLE.test(year)) message = "year must be a whole number";
    else if (copies !== "" && !(WHOLE.test(copies) && Number(copies) > 0)) message = "copies must be a positive whole number";
    if (message) {
      result.errors.push({ line, message });
      continue;
    }
    const tags = get("tags");
    addBook(store, {
      title,
      author,
      year: Number(year),
      tags: tags ? tags.split(";") : [],
      copies: copies === "" ? 1 : Number(copies),
    });
    result.added++;
  }
  return result;
}
